import { NapiCli } from '@napi-rs/cli';
const build = await new NapiCli().build({
  manifestPath: 'native/Cargo.toml',
  packageJsonPath: 'package.json',
  outputDir: 'dist',
  target: process.env.CARGO_BUILD_TARGET,
  platform: true,
  esm: true,
  release: true,
  jsBinding: 'index.js',
  dts: 'index.d.ts',
  dtsHeader:
    "/* Generated by napi-rs. Do not edit. */\nimport type { ScanEntry, ScanOptions, ScanResult, Source, Checkpoint, Report, Manifest, Target, GlobalAccess, AnalysisInstance, Resource, Budgets } from './types.js';\nexport * from './types.js';",
  cargoOptions: ['--locked'],
});
await build.task;
